<?php
/** @var array $meeting @var array $registration @var array $choices @var array $choice_states @var array $registration_state @var string $token @var string $error */
$editing = ! empty($registration['id']);
$participants = (array) ($registration['participants'] ?? array());
if (! $participants) {
    $participants[] = array('id' => 'person_1', 'first_name' => '', 'last_name' => '', 'email' => '', 'phone' => '', 'relationship' => '', 'vessels' => array(), 'activities' => array(), 'dietary' => array('none'), 'dietary_other' => '', 'allergy_note' => '', 'primary' => 1);
}
$roles = array('supporter' => 'Stödmedlem', 'representative' => 'Fartygsombud', 'vessel_member' => 'Medlem/representant från fartyg', 'companion' => 'Medföljande', 'other' => 'Övrig');
if (! empty($meeting['allow_guest'])) { $roles['guest'] = 'Inbjuden gäst'; }
$activity_answers = (array) ($registration['activity_answers'] ?? array());
$person_name = static function (array $person, int $index): string { return trim((string) ($person['first_name'] ?? '') . ' ' . (string) ($person['last_name'] ?? '')) ?: sprintf(__('Person %d', 'ssf-member-portal'), $index + 1); };
?>
<section class="ssf-am-page" aria-labelledby="ssf-am-registration-heading">
<header class="ssf-am-intro"><p class="ssf-am-eyebrow"><?php echo esc_html(get_the_title((int) $meeting['id'])); ?></p><h1 id="ssf-am-registration-heading"><?php echo $editing ? esc_html__('Ändra din anmälan', 'ssf-member-portal') : esc_html__('Anmälan till årsmöteshelgen', 'ssf-member-portal'); ?></h1><p class="ssf-am-dates"><?php echo esc_html($this->date_range($meeting)); ?><?php if ($meeting['location']) : ?> · <?php echo esc_html($meeting['location']); ?><?php endif; ?></p></header>
<?php if ($error) : ?><p class="ssf-am-message ssf-am-message--error" role="alert" tabindex="-1" data-ssf-error-message><?php echo esc_html($error); ?></p><?php endif; ?>
<?php if (empty($registration_state['can_register'])) : ?><p class="ssf-am-message"><?php echo esc_html((string) ($registration_state['message'] ?? __('Anmälan är stängd.', 'ssf-member-portal'))); ?></p><?php else : ?>
<form class="ssf-am-form ssf-am-group-form" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post" data-ssf-group-registration>
<input type="hidden" name="action" value="ssf_member_portal_submit_meeting_registration"><?php wp_nonce_field('ssf_member_portal_submit_meeting_registration', 'ssf_member_portal_meeting_registration_nonce'); ?><?php if ($editing) : ?><input type="hidden" name="token" value="<?php echo esc_attr($token); ?>"><?php endif; ?><p class="ssf-am-honeypot" aria-hidden="true"><label>Webbplats<input name="website" tabindex="-1" autocomplete="off"></label></p>
<ol class="ssf-am-steps" aria-label="Steg i anmälan"><?php foreach (array(1 => 'Deltagare', 2 => 'Program & aktiviteter', 3 => 'Granska') as $step => $label) : ?><li data-ssf-step-indicator="<?php echo esc_attr((string) $step); ?>"><span><?php echo esc_html((string) $step); ?></span><?php echo esc_html(sprintf(__('Steg %1$d av 3 – %2$s', 'ssf-member-portal'), $step, $label)); ?></li><?php endforeach; ?></ol>

<section class="ssf-am-step" data-ssf-step="1"><h2 tabindex="-1">1. Deltagare</h2><p class="ssf-am-help">Den första personen är huvudanmälare och kontaktperson.</p><div data-ssf-participants>
<?php foreach ($participants as $index => $person) : $person_id = (string) ($person['id'] ?? ('person_' . ($index + 1))); ?><article class="ssf-am-person-card" data-ssf-person data-person-index="<?php echo esc_attr((string) $index); ?>" data-person-id="<?php echo esc_attr($person_id); ?>"><header><strong data-ssf-person-heading><?php echo esc_html($person_name($person, $index)); ?></strong><?php if (0 === $index) : ?><span>Huvudanmälare</span><?php else : ?><button type="button" class="ssf-am-text-button" data-ssf-remove-person>Ta bort</button><?php endif; ?></header><input type="hidden" name="participants[<?php echo esc_attr((string) $index); ?>][id]" value="<?php echo esc_attr($person_id); ?>">
<div class="ssf-am-grid"><p><label>Förnamn *<input name="participants[<?php echo esc_attr((string) $index); ?>][first_name]" required value="<?php echo esc_attr((string) ($person['first_name'] ?? '')); ?>" data-ssf-person-name></label></p><p><label>Efternamn *<input name="participants[<?php echo esc_attr((string) $index); ?>][last_name]" required value="<?php echo esc_attr((string) ($person['last_name'] ?? '')); ?>" data-ssf-person-name></label></p></div>
<div class="ssf-am-grid"><p><label>E-post<?php echo 0 === $index ? ' *' : ''; ?><input type="email" name="participants[<?php echo esc_attr((string) $index); ?>][email]" <?php echo 0 === $index ? 'required' : ''; ?> value="<?php echo esc_attr((string) ($person['email'] ?? '')); ?>"></label></p><p><label>Telefon<input type="tel" name="participants[<?php echo esc_attr((string) $index); ?>][phone]" value="<?php echo esc_attr((string) ($person['phone'] ?? '')); ?>"></label></p></div>
<div class="ssf-am-grid"><p><label>Medlemskap/roll *<select name="participants[<?php echo esc_attr((string) $index); ?>][relationship]" required><option value="">Välj</option><?php foreach ($roles as $value => $label) : ?><option value="<?php echo esc_attr($value); ?>" <?php selected((string) ($person['relationship'] ?? ''), $value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label></p><p><label>Fartyg<input name="participants[<?php echo esc_attr((string) $index); ?>][vessels][]" value="<?php echo esc_attr(implode(', ', (array) ($person['vessels'] ?? array()))); ?>"></label></p></div></article><?php endforeach; ?></div>
<template data-ssf-person-template><article class="ssf-am-person-card" data-ssf-person data-person-index="__INDEX__"><header><strong data-ssf-person-heading>Person __NUMBER__</strong><button type="button" class="ssf-am-text-button" data-ssf-remove-person>Ta bort</button></header><input type="hidden" name="participants[__INDEX__][id]" value="person___TOKEN__"><div class="ssf-am-grid"><p><label>Förnamn *<input name="participants[__INDEX__][first_name]" required data-ssf-person-name></label></p><p><label>Efternamn *<input name="participants[__INDEX__][last_name]" required data-ssf-person-name></label></p></div><div class="ssf-am-grid"><p><label>E-post<input type="email" name="participants[__INDEX__][email]"></label></p><p><label>Telefon<input type="tel" name="participants[__INDEX__][phone]"></label></p></div><div class="ssf-am-grid"><p><label>Medlemskap/roll *<select name="participants[__INDEX__][relationship]" required><option value="">Välj</option><?php foreach ($roles as $value => $label) : ?><option value="<?php echo esc_attr($value); ?>"><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label></p><p><label>Fartyg<input name="participants[__INDEX__][vessels][]"></label></p></div></article></template>
<p><button type="button" class="ssf-am-button ssf-am-button--secondary" data-ssf-add-person>+ Lägg till person</button></p><p class="ssf-am-step-actions"><button type="button" class="ssf-am-button" data-ssf-next>Fortsätt</button></p></section>

<section class="ssf-am-step" data-ssf-step="2"><h2 tabindex="-1">2. Program & aktiviteter</h2><p class="ssf-am-help">Välj individuellt vilka aktiviteter varje person deltar i.</p><div data-ssf-activity-list><?php foreach ($choices as $choice) : $key = (string) $choice['key']; $state = $choice_states[$key] ?? array(); ?><article class="ssf-am-activity-card" data-ssf-activity="<?php echo esc_attr($key); ?>" data-food="<?php echo ! empty($choice['food']) ? '1' : '0'; ?>" data-disabled="<?php echo empty($state['available']) ? '1' : '0'; ?>"><header><div><h3><?php echo esc_html($choice['title']); ?></h3><p><?php echo esc_html(implode(' · ', array_filter(array((string) ($choice['date'] ?? ''), (string) ($choice['start'] ?? ''), (string) ($choice['location'] ?? ''), (string) ($choice['price'] ?? ''))))); ?></p></div><strong data-ssf-activity-count>0 personer</strong></header><?php if (! empty($choice['description'])) : ?><p><?php echo esc_html($choice['description']); ?></p><?php endif; ?><div data-ssf-activity-people><?php foreach ($participants as $index => $person) : $activity_person_id = (string) ($person['id'] ?? ('person_' . ($index + 1))); ?><label class="ssf-am-option"><input type="checkbox" data-person-id="<?php echo esc_attr($activity_person_id); ?>" name="participants[<?php echo esc_attr((string) $index); ?>][activities][<?php echo esc_attr($key); ?>]" value="1" <?php checked(! empty($person['activities'][$key])); ?> <?php disabled(empty($state['available']) && empty($person['activities'][$key])); ?>> <span><?php echo esc_html($person_name($person, $index)); ?></span></label><?php endforeach; ?></div></article><?php endforeach; ?></div><h3>Frågor för valda aktiviteter</h3><p class="ssf-am-help">Här visas endast frågor för aktiviteter som respektive deltagare har valt.</p><div data-ssf-activity-question-list><?php $has_activity_questions = false; foreach ($choices as $choice) : foreach ((array) ($choice['questions'] ?? array()) as $question) : $has_activity_questions = true; $this->render_activity_question($choice, $question, $participants, $activity_answers); endforeach; endforeach; ?><p data-ssf-no-activity-questions <?php echo $has_activity_questions ? 'hidden' : ''; ?>>Inga extra frågor gäller för de valda aktiviteterna.</p></div><p class="ssf-am-step-actions"><button type="button" class="ssf-am-text-button" data-ssf-back>Tillbaka</button><button type="button" class="ssf-am-button" data-ssf-next>Granska</button></p></section>

<section class="ssf-am-step" data-ssf-step="3"><h2 tabindex="-1">3. Granska</h2><div data-ssf-review aria-live="polite"></div><?php if ($meeting['questions']) : ?><fieldset><legend>Övriga frågor</legend><?php foreach ($meeting['questions'] as $question) : if (! empty($question['visible'])) { $this->render_question($question, (array) ($registration['answers'] ?? array())); } endforeach; ?></fieldset><?php endif; ?><?php if (class_exists('SSF_Antispam')) { \SSF_Antispam::render('annual_meeting_registration'); } ?><p class="ssf-am-step-actions"><button type="button" class="ssf-am-text-button" data-ssf-back>Ändra</button><button class="ssf-am-button" type="submit" data-ssf-submit data-sending-label="Skickar…"><?php echo $editing ? esc_html__('Spara ändringar', 'ssf-member-portal') : esc_html__('Skicka anmälan', 'ssf-member-portal'); ?></button></p></section>
</form>
<?php if ($editing && 'cancelled' !== ($registration['status'] ?? '')) : ?><form class="ssf-am-cancel" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="ssf_member_portal_cancel_meeting_registration"><input type="hidden" name="token" value="<?php echo esc_attr($token); ?>"><?php wp_nonce_field('ssf_member_portal_cancel_meeting_registration', 'ssf_member_portal_meeting_cancel_nonce'); ?><button type="submit" class="ssf-am-text-button">Avboka anmälan</button></form><?php endif; ?>
<?php endif; ?></section>
